mapper.select:
select count(*) from business_audit_event
where domain_type = 'MERCHANT' and domain_id = #{merchantId}
  and owner_member_id = #{ownerMemberId} and actor_member_id = #{actorMemberId}
  and target_type = 'MERCHANT_REVIEW' and target_id = #{reviewId}
  and action = #{action} and request_id = #{requestId}
